#include <string>
#include <sstream>
#include <cmath>

class Solution {
public:
    bool isLeap(int y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }
    int daysSince1971(std::string date) {
        int y, m, d;
        char dash1, dash2;
        std::stringstream ss(date);
        ss >> y >> dash1 >> m >> dash2 >> d;
        int days = d;
        int monthDays[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        for (int curY = 1971; curY < y; ++curY) {
            days += isLeap(curY) ? 366 : 365;
        }
        for (int curM = 1; curM < m; ++curM) {
            days += monthDays[curM];
            if (curM == 2 && isLeap(y)) days++;
        }
        return days;
    }
    int daysBetweenDates(std::string date1, std::string date2) {
        return std::abs(daysSince1971(date1) - daysSince1971(date2));
    }
};

class Solution {
    private boolean isLeap(int y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }
    private int daysSince1971(String date) {
        String[] parts = date.split("-");
        int y = Integer.parseInt(parts[0]), m = Integer.parseInt(parts[1]), d = Integer.parseInt(parts[2]);
        int days = d;
        int[] monthDays = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        for (int curY = 1971; curY < y; curY++) {
            days += isLeap(curY) ? 366 : 365;
        }
        for (int curM = 1; curM < m; curM++) {
            days += monthDays[curM];
            if (curM == 2 && isLeap(y)) days++;
        }
        return days;
    }
    public int daysBetweenDates(String date1, String date2) {
        return Math.abs(daysSince1971(date1) - daysSince1971(date2));
